// Helper functions for ID generation (as they are not provided as separate components in REAL IMPLEMENTATION CONTEXT)
// These are simple placeholders to satisfy the logic component dependencies.
const generateUUID = () =>
  Math.random().toString(36).substring(2, 15) +
  Math.random().toString(36).substring(2, 15);
let epicCodeCounter = 0; // Use a separate counter for codes
const generateEpicId = (projectId) =>
  `EP-${String(++epicCodeCounter).padStart(3, "0")}`;
let storyCodeCounter = 0; // Use a separate counter for codes
const generateStoryId = (epicId) =>
  `ST-${String(++storyCodeCounter).padStart(3, "0")}`;

// Helper functions for progress calculation and status derivation (as they are not provided as separate components in REAL IMPLEMENTATION CONTEXT)
// These are simple placeholders to satisfy the logic component dependencies.
const calculateProjectProgress = (epics = []) => {
  if (epics.length === 0) return 0;
  const totalProgress = epics.reduce(
    (sum, epic) => sum + (epic.progress || 0),
    0,
  );
  return Math.round(totalProgress / epics.length);
};

const calculateEpicProgress = (stories = []) => {
  if (stories.length === 0) return 0;
  const totalProgress = stories.reduce(
    (sum, story) => sum + (story.progress || 0),
    0,
  );
  return Math.round(totalProgress / stories.length);
};

const deriveStatus = (progress, isBlocked, entityType) => {
  if (isBlocked) return "BLOCKED";
  if (progress === 0) return "NOT_STARTED";
  if (progress === 100) return "COMPLETED";
  return "IN_PROGRESS";
};

// Utility for current date/datetime in ISO 8601 format
const getCurrentISODate = () => new Date().toISOString().split("T")[0];
const getCurrentISODatetime = () => new Date().toISOString();

